let currentDisplayMonth=new Date().getMonth();let currentDisplayYear=new Date().getFullYear();document.addEventListener('DOMContentLoaded',function(){const priceData=json_price_per_date;const FirstDate=random_date_first_date;let currentDate;if(FirstDate!==''){currentDate=new Date(FirstDate)}else{currentDate=new Date();currentDate.setDate(1);currentDate.setMonth(currentDate.getMonth()+1)}
const currentMonth=currentDate.getMonth();const currentYear=currentDate.getFullYear();renderTwoMonths(currentMonth,currentYear,priceData);initNavigation();bookingBtn();filterHotelByStar()});function filterHotelByStar(){document.querySelectorAll('.hotel-category-filter').forEach(fl=>{const star=fl.getAttribute('data-star');const item_class='.hotel-category-'+star;const item_class_active='.active.hotel-category';fl.addEventListener('change',function(){document.querySelectorAll(item_class_active).forEach(el=>{el.classList.remove('active')});document.querySelectorAll(item_class).forEach(el=>{el.classList.add('active')})})})}
function bookingBtn(){const btnBooking=document.querySelector('.btn-redirect-booking');const url=btnBooking.getAttribute('data-url');btnBooking.addEventListener('click',function(event){event.preventDefault();let dateS=btnBooking.getAttribute('data-date');window.location.href=url+'&date='+dateS})}
function renderTwoMonths(startMonth,startYear,priceData){const container=document.getElementById('calendarContainer');container.innerHTML='';renderMonth(startMonth,startYear,priceData);const nextMonth=startMonth===11?0:startMonth+1;const nextYear=startMonth===11?startYear+1:startYear;renderMonth(nextMonth,nextYear,priceData)}
function updateCalendar(direction){const priceData=json_price_per_date;if(direction==='next'){currentDisplayMonth+=2;if(currentDisplayMonth>11){currentDisplayMonth-=12;currentDisplayYear+=1}}else{currentDisplayMonth-=2;if(currentDisplayMonth<0){currentDisplayMonth+=12;currentDisplayYear-=1}}
document.getElementById('monthSelect1').value=currentDisplayMonth;document.getElementById('yearSelect').value=currentDisplayYear;renderTwoMonths(currentDisplayMonth,currentDisplayYear,priceData)}
function initNavigation(){const header=document.createElement('div');header.className='row align-items-center justify-content-between row-gap-10';const backBtn=document.createElement('span');backBtn.innerHTML='<svg width="16" height="16" viewBox="0 0 24 24" fill="#bd1e2d" style="vertical-align:middle;">\n'+'    <polygon points="15,4 5,12 15,20"></polygon>\n'+'  </svg> Back';backBtn.className='d-flex align-items-center gap-10 cursor-pointer';backBtn.onclick=()=>updateCalendar('back');const monthSelect1=document.createElement('select');monthSelect1.id='monthSelect1';monthSelect1.className='pt-5 pb-5';const yearSelect=document.createElement('select');yearSelect.id='yearSelect';yearSelect.className='pt-5 pb-5';const monthSelect2=document.createElement('select');monthSelect2.id='monthSelect2';monthSelect2.className='pt-5 pb-5';const nextBtn=document.createElement('span');nextBtn.innerHTML='Next   <svg width="16" height="16" viewBox="0 0 24 24" fill="#bd1e2d" style="vertical-align:middle;">\n'+'    <polygon points="9,4 19,12 9,20"></polygon>\n'+'  </svg>';nextBtn.className='d-flex align-items-center justify-content-right gap-10 cursor-pointer';nextBtn.onclick=()=>updateCalendar('next');let monthNames=[];if(current_language==='pt'){monthNames=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro']}else if(current_language==='en'){monthNames=['January','February','March','April','May','June','July','August','September','October','November','December']}else{monthNames=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']}
monthNames.forEach((month,index)=>{const option=document.createElement('option');option.value=index;option.textContent=month;monthSelect1.appendChild(option)});const currentYear=new Date().getFullYear();for(let i=0;i<3;i++){const option=document.createElement('option');option.value=currentYear+i;option.textContent=currentYear+i;yearSelect.appendChild(option)}
monthNames.forEach((month,index)=>{const option=document.createElement('option');option.value=index;option.textContent=month});const currentMonth=new Date().getMonth()+1;monthSelect1.value=currentMonth;yearSelect.value=currentYear;monthSelect1.addEventListener('change',updateFromSelect);yearSelect.addEventListener('change',updateFromSelect);const backBtnWrapper=document.createElement('div');backBtnWrapper.className='col-md-3 col-6';backBtnWrapper.appendChild(backBtn);header.appendChild(backBtnWrapper);const centerWrapper=document.createElement('div');centerWrapper.className='col-md-6 col-lg-5 sm-order-1';const centerWrapperInner=document.createElement('div');centerWrapperInner.className='row md-col-gap-20';const colWrapper=document.createElement('div');colWrapper.className='col-6';colWrapper.appendChild(monthSelect1);const colWrapper2=document.createElement('div');colWrapper2.className='col-6';colWrapper2.appendChild(yearSelect);centerWrapperInner.appendChild(colWrapper);centerWrapperInner.appendChild(colWrapper2);centerWrapper.appendChild(centerWrapperInner);header.appendChild(centerWrapper);const nextBtnWrapper=document.createElement('div');nextBtnWrapper.className='col-md-3 col-6';nextBtnWrapper.appendChild(nextBtn);header.appendChild(nextBtnWrapper);const calendarContainer=document.getElementById('calendarContainer');calendarContainer.parentNode.insertBefore(header,calendarContainer)}
function updateFromSelect(){const priceData=json_price_per_date;const month1=parseInt(document.getElementById('monthSelect1').value);const year=parseInt(document.getElementById('yearSelect').value);currentDisplayMonth=month1;currentDisplayYear=year;renderTwoMonths(month1,year,priceData)}
function renderMonth(month,year,priceData){const container=document.getElementById('calendarContainer');const monthEl=document.createElement('div');monthEl.className='calendar';let monthNames=[];if(current_language==='pt'){monthNames=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro']}else if(current_language==='en'){monthNames=['January','February','March','April','May','June','July','August','September','October','November','December']}else{monthNames=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']}
const monthHeader=document.createElement('div');monthHeader.className='month-header';monthHeader.textContent=`${monthNames[month]} ${year}`;monthEl.appendChild(monthHeader);const weekdaysEl=document.createElement('div');weekdaysEl.className='weekdays';let weekdayNames;if(current_language==='pt'){weekdayNames=['Do','Se','Te','Qa','Qi','Se','Sa']}else if(current_language==='en'){weekdayNames=['Su','Mo','Tu','We','Th','Fr','Sa']}else{weekdayNames=['Do','Lu','Ma','Mi','Ju','Vi','Sa']}
weekdayNames.forEach(day=>{const dayEl=document.createElement('div');dayEl.className='weekday';dayEl.textContent=day;weekdaysEl.appendChild(dayEl)});monthEl.appendChild(weekdaysEl);const daysEl=document.createElement('div');daysEl.className='days';const firstDay=new Date(year,month,1);const lastDay=new Date(year,month+1,0);const startDay=new Date(firstDay);startDay.setDate(1-firstDay.getDay());const endDay=new Date(lastDay);endDay.setDate(lastDay.getDate()+(6-lastDay.getDay()));const currentDate=new Date();const currentDay=new Date(startDay);while(currentDay<=endDay){const dayEl=document.createElement('div');dayEl.className='day';dayEl.setAttribute('data-date',formatDate(currentDay));if(currentDay.setHours(0,0,0,0)<currentDate.setHours(0,0,0,0)){dayEl.classList.add('is-past')}
if(currentDay.getMonth()!==month){dayEl.classList.add('other-month')}
const dayNumber=document.createElement('div');dayNumber.className='day-number';dayNumber.textContent=currentDay.getDate();dayEl.appendChild(dayNumber);const dateStr=formatDate(currentDay);if(priceData[dateStr]){const priceEl=document.createElement('div');priceEl.className='price';priceEl.textContent=priceData[dateStr];dayEl.appendChild(priceEl)}
dayEl.addEventListener('click',function(){document.querySelectorAll('.day.selected').forEach(el=>{el.classList.remove('selected')});this.classList.add('selected');document.querySelector('.btn-redirect-booking').setAttribute('data-date',dayEl.getAttribute('data-date'));document.querySelector('.btn-redirect-booking').click()});daysEl.appendChild(dayEl);currentDay.setDate(currentDay.getDate()+1)}
monthEl.appendChild(daysEl);container.appendChild(monthEl)}
function formatDate(date){const d=new Date(date);return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`}